import java.io.BufferedInputStream

private const val MOD = 1_000_000_007L

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextLong(): Long {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }

        var result = 0L
        while (c > 32 && c != -1) {
            result = result * 10 + (c - '0'.code)
            c = readByte()
        }
        return if (sign == 1) result else -result
    }
}

private fun multiply(
    one: Array<LongArray>,
    two: Array<LongArray>
): Array<LongArray> {
    val size = one.size
    val result = Array(size) { LongArray(size) }

    for (i in 0 until size) {
        for (j in 0 until size) {
            for (k in 0 until size) {
                result[i][j] =
                    (result[i][j] + one[i][k] * two[k][j] % MOD) % MOD
            }
        }
    }
    return result
}

private fun power(exp: Long, base: Array<LongArray>): Array<LongArray> {
    if (exp == 1L) return base

    var result = power(exp / 2, base)
    result = multiply(result, result)
    if (exp and 1L == 1L) {
        result = multiply(result, base)
    }
    return result
}

fun main() {
    val scanner = FastScanner()
    val n = scanner.nextLong()
    val m = scanner.nextLong()

    if (n < m) {
        print("1")
        return
    }
    if (n == m) {
        print("2")
        return
    }

    val size = m.toInt()
    val matrix = Array(size) { LongArray(size) }
    matrix[0][0] = 1L
    matrix[0][size - 1] = 1L

    for (i in 1 until size) {
        matrix[i][i - 1] = 1L
    }

    println(power(n, matrix)[0][0])
}

