import java.io.BufferedInputStream
import java.io.PrintWriter

private const val MOD = 1_000_000_007L
private var m = 0

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextLong(): Long {
        var c = readByte()
        while (c <= 32 && c != -1) c = readByte()

        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }

        var result = 0L
        while (c > 32 && c != -1) {
            result = result * 10 + (c - '0'.code)
            c = readByte()
        }
        return if (sign == 1) result else -result
    }
}

private fun multiply(one: Array<IntArray>, two: Array<IntArray>): Array<IntArray> {
    val result = Array(m) { IntArray(m) }

    for (i in 0 until m) {
        for (j in 0 until m) {
            for (k in 0 until m) {
                result[i][j] = (
                    result[i][j].toLong() +
                        one[i][k].toLong() * two[k][j] % MOD
                    ).rem(MOD).toInt()
            }
        }
    }

    return result
}

private fun power(exp: Long, base: Array<IntArray>): Array<IntArray> {
    if (exp == 1L) return base

    var result = power(exp / 2, base)
    result = multiply(result, result)

    if (exp and 1L == 1L) {
        result = multiply(result, base)
    }

    return result
}

fun main() {
    val scanner = FastScanner()
    val writer = PrintWriter(System.out)

    val n = scanner.nextLong()
    m = scanner.nextLong().toInt()

    when {
        n < m.toLong() -> writer.print(1)
        n == m.toLong() -> writer.print(2)
        else -> {
            val matrix = Array(m) { IntArray(m) }
            matrix[0][0] = 1
            matrix[0][m - 1] = 1

            for (i in 1 until m) {
                matrix[i][i - 1] = 1
            }

            writer.println(power(n, matrix)[0][0])
        }
    }

    writer.flush()
}

